import{_t as e,it as t,n,rt as r}from"./chunks/framework.GGfqtSwG.js";var i=JSON.parse(`{"title":"DIY Kilder","description":"","frontmatter":{},"headers":[],"relativePath":"diykilder.md","filePath":"diykilder.md"}`),a={name:`diykilder.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="diy-kilder" tabindex="-1">DIY Kilder <a class="header-anchor" href="#diy-kilder" aria-label="Permalink to “DIY Kilder”">​</a></h1><p>Når du skal købe DIY hormonbehandling kan det godt virke overvældende da der er så mange forskellige sælgere som alle har problemer med mangel. Herunder kan du se de 2 primære sider som holder styr på hvilke sælgere der har hormoner på lager. Jeg vil anbefale at holde øje med de her sider for at finde sælgere som har hormoner på lager.</p><ul><li><a href="https://valerie.vg/" target="_blank" rel="noreferrer">valerie.vg</a> - Valerie er min go-to, og vil højt anbefale den.</li><li><a href="https://diyhrt.coffee/" target="_blank" rel="noreferrer">diyhrt.coffee</a> - Også en fantastisk side, men mangler penge. <a href="https://diyhrt.coffee/donate" target="_blank" rel="noreferrer">Donér</a> hvis du kan.</li></ul><p>Disse sider har kun information om hvor du kan købe feminiserende hormoner. For information om maskuliserende hormonbehandling, se <a href="https://diyhrt.info/transmasc/sources/" target="_blank" rel="noreferrer">diyhrt.info</a>.</p>`,4)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};